73	// ascending name order, together with the snapshot cursor each points at. The
74	// gate runs first in the transaction (404 for an unregistered device, 403 for
75	// a revoked one); an unknown document or a document without markers then
76	// reads as an empty list rather than an error. It writes nothing.
77	func (s *Service) ListSnapshotVersions(documentID, deviceID string) ([]SnapshotVersion, error) {
78		tx, err := s.db.Begin()
79		if err != nil {
80			return nil, err
81		}
