83	
84		if err := gateTx(s, tx, documentID, deviceID); err != nil {
85			return nil, err
86		}
87	
88		rows, err := tx.Query(
89			`SELECT name, cursor FROM snapshot_versions
90			 WHERE document_id = ? ORDER BY name ASC`,
91			documentID,
92		)
93		if err != nil {
94			return nil, err
95		}
96		defer func() { _ = rows.Close() }()
97	
98		out := make([]SnapshotVersion, 0)
99		for rows.Next() {
100			var v SnapshotVersion
101			if err := rows.Scan(&v.Name, &v.Cursor); err != nil {
102				return nil, err
103			}
104			out = append(out, v)
105		}
106		if err := rows.Err(); err != nil {
107			return nil, err
108		}
109		return out, tx.Commit()
110	}
