112	// GetSnapshotVersionState resolves a version name to its snapshot and returns
113	// that snapshot's cursor and stored state, exactly as GetSnapshot would for
114	// the cursor. The gate runs first; a name without a marker is
115	// ErrVersionNotFound and a marker whose snapshot is gone is
116	// ErrSnapshotNotFound — the caller maps both to 404 and exposes no content.
117	func (s *Service) GetSnapshotVersionState(documentID, deviceID, name string) (int64, json.RawMessage, error) {
118		tx, err := s.db.Begin()
119		if err != nil {
120			return 0, nil, err
121		}
122		defer func() { _ = tx.Rollback() }()
123	
124		if err := gateTx(s, tx, documentID, deviceID); err != nil {
125			return 0, nil, err
126		}
127	
128		var cursor int64
129		err = tx.QueryRow(
130			`SELECT cursor FROM snapshot_versions WHERE document_id = ? AND name = ?`,
131			documentID, name,
132		).Scan(&cursor)
133		switch {
134		case errors.Is(err, sql.ErrNoRows):
135			return 0, nil, ErrVersionNotFound
136		case err != nil:
137			return 0, nil, err
138		}
139	
140		var state []byte
141		if err := tx.QueryRow(
142			`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
143			documentID, cursor,
144		).Scan(&state); err != nil {
145			if errors.Is(err, sql.ErrNoRows) {
146				return 0, nil, ErrSnapshotNotFound
147			}
148			return 0, nil, err
149		}
150		return cursor, json.RawMessage(state), tx.Commit()
151	}
