112	// Same name + same cursor is idempotent with the identical body and zero extra
113	// rows; a different cursor is a 409 and leaves the binding untouched.
114	func TestSessionSnapshotVersionRegisterIdempotentAndConflict(t *testing.T) {
115		h, _ := newTestHandler(t)
