117	
118		first := sessionRegisterVersion(t, h, "sess", "doc", "v1", 1)
119		w, _ := postJSON(t, h, sessionVersionsCollection("sess", "doc"), map[string]any{
120			"name": "v1", "snapshotCursor": 1,
121		})
122		if w.Code != http.StatusOK || strings.TrimSpace(w.Body.String()) != first {
123			t.Fatalf("idempotent body = %d %q, want %q", w.Code, w.Body.String(), first)
124		}
125		w, _ = doRequest(t, h, http.MethodGet, sessionVersionsCollection("sess", "doc"))
126		if strings.Count(w.Body.String(), `"name":"v1"`) != 1 {
127			t.Fatalf("idempotent registration added a row: %s", w.Body.String())
128		}
129	
130		// Rebind to another cursor: 409, structured conflictName, zero writes.
131		w, _ = postJSON(t, h, sessionVersionsCollection("sess", "doc"), map[string]any{
132			"name": "v1", "snapshotCursor": 2,
133		})
134		if w.Code != http.StatusConflict {
135			t.Fatalf("rebind = %d, want 409, %s", w.Code, w.Body.String())
136		}
137		if got := strings.TrimSpace(w.Body.String()); got != `{"conflictName":"v1","error":"snapshot version is already bound to another cursor"}` {
138			t.Fatalf("conflict body = %q", got)
139		}
140		wg, _ := doRequest(t, h, http.MethodGet, sessionVersionItem("sess", "doc", "v1"))
141		if !strings.Contains(wg.Body.String(), `"cursor":1`) {
142			t.Fatalf("conflict moved the binding: %s", wg.Body.String())
143		}
144	}
